ALTER TABLE public.official_brokers_registry ADD COLUMN IF NOT EXISTS display_name text;
ALTER TABLE public.official_brokers_registry ADD COLUMN IF NOT EXISTS registry_city text;
COMMENT ON COLUMN public.official_brokers_registry.holder_name IS 'Raw official surname-first evidence, preserved for exact certificate matching';
COMMENT ON COLUMN public.official_brokers_registry.display_name IS 'First-name last-name presentation; raw holder_name remains the identity evidence';
CREATE OR REPLACE FUNCTION public.official_broker_name(_uid uuid,_license text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT COALESCE(NULLIF(btrim(r.display_name),''),NULLIF(btrim(r.holder_name),'')) FROM public.official_brokers_registry r WHERE r.license_number=_license ORDER BY r.source_updated_at DESC NULLS LAST LIMIT 1),(SELECT NULLIF(btrim(v.registry_holder_name),'') FROM public.broker_license_verifications v WHERE v.user_id=_uid AND v.license_number=_license ORDER BY v.verified_at DESC LIMIT 1)) $$;
CREATE OR REPLACE FUNCTION public.protect_locked_broker_name() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _official_name text; _has_evidence boolean:=false; _canonical text; BEGIN
 IF TG_OP='UPDATE' THEN SELECT registry_holder_name INTO _official_name FROM public.broker_license_verifications WHERE user_id=OLD.id AND license_number=OLD.broker_license_number; _has_evidence:=FOUND; END IF;
 _canonical:=public.official_broker_name(NEW.id,NEW.broker_license_number);
 IF TG_OP='UPDATE' AND OLD.locked_broker_name IS NOT NULL THEN
  IF NEW.locked_broker_name IS DISTINCT FROM OLD.locked_broker_name AND NEW.locked_broker_name=_canonical AND public.broker_name_tokens(OLD.locked_broker_name)=public.broker_name_tokens(_canonical) THEN NEW.full_name:=_canonical;
  ELSE NEW.locked_broker_name:=OLD.locked_broker_name; NEW.full_name:=OLD.locked_broker_name; END IF;
 ELSIF NEW.locked_broker_name IS NOT NULL THEN
  IF auth.role() IS DISTINCT FROM 'service_role' AND (NOT public.publisher_sms_verified() OR NEW.id IS DISTINCT FROM auth.uid() OR NOT public.partner_can_view_closing(NEW.id) OR NEW.locked_broker_name IS DISTINCT FROM _canonical) THEN RAISE EXCEPTION 'server_identity_required'; END IF; NEW.full_name:=NEW.locked_broker_name;
 ELSIF _has_evidence AND auth.role() IS DISTINCT FROM 'service_role' THEN NEW.full_name:=COALESCE(_canonical,_official_name,OLD.full_name); END IF;
 IF TG_OP='UPDATE' AND OLD.locked_broker_city IS NOT NULL THEN IF auth.role() IS DISTINCT FROM 'service_role' THEN NEW.locked_broker_city:=OLD.locked_broker_city; END IF;
 ELSIF NEW.locked_broker_city IS NOT NULL AND auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'server_identity_required'; END IF;
 IF NEW.locked_broker_city IS NOT NULL THEN NEW.city:=NULLIF(NEW.locked_broker_city,''); ELSIF TG_OP='UPDATE' AND (OLD.locked_broker_name IS NOT NULL OR _has_evidence) AND auth.role() IS DISTINCT FROM 'service_role' THEN NEW.city:=OLD.city; END IF; RETURN NEW; END $$;
UPDATE public.official_brokers_registry r SET display_name=COALESCE((SELECT v.account_name_before_verification FROM public.broker_license_verifications v WHERE v.license_number=r.license_number AND btrim(v.account_name_before_verification)<>btrim(r.holder_name) AND public.broker_name_tokens(v.account_name_before_verification)=public.broker_name_tokens(r.holder_name) LIMIT 1),CASE WHEN position(' ' in btrim(r.holder_name))>0 THEN substring(btrim(r.holder_name) from position(' ' in btrim(r.holder_name))+1)||' '||split_part(btrim(r.holder_name),' ',1) ELSE btrim(r.holder_name) END) WHERE display_name IS NULL;
UPDATE public.profiles p SET full_name=r.display_name,locked_broker_name=CASE WHEN p.locked_broker_name IS NOT NULL THEN r.display_name ELSE NULL END FROM public.official_brokers_registry r,public.broker_license_verifications v WHERE v.user_id=p.id AND v.license_number=p.broker_license_number AND r.license_number=v.license_number AND r.display_name IS NOT NULL AND (p.locked_broker_name IS NOT NULL OR public.broker_name_tokens(p.full_name)=public.broker_name_tokens(r.holder_name));